#include "phase.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct Phase {
    const char *name;
    double wall_ms;
    double cpu_ms;
    unsigned count;
} Phase;
static Phase phases[48];
static size_t used;
static size_t active;
static double wall_start, cpu_start, wall_last, cpu_last;

static double stamp(clockid_t clock) {
    struct timespec value;
    if (clock_gettime(clock, &value) != 0) abort();
    return (double)value.tv_sec * 1000.0 + (double)value.tv_nsec / 1000000.0;
}

void phase_set(const char *name) {
    double wall = stamp(CLOCK_MONOTONIC), cpu = stamp(CLOCK_PROCESS_CPUTIME_ID);
    if (used == 0) {
        wall_start = wall;
        cpu_start = cpu;
    } else {
        phases[active].wall_ms += wall - wall_last;
        phases[active].cpu_ms += cpu - cpu_last;
    }
    size_t slot = 0;
    while (slot < used && strcmp(phases[slot].name, name) != 0) ++slot;
    if (slot == used) {
        if (used == sizeof(phases) / sizeof(phases[0])) abort();
        phases[used++].name = name;
    }
    phases[slot].count += 1;
    active = slot;
    wall_last = wall;
    cpu_last = cpu;
}

void phase_dump(void) {
    phase_set("finished");
    fprintf(stderr, "PHASE {\"wall_ms\":%.9f,\"cpu_ms\":%.9f,\"phases\":{",
        wall_last - wall_start, cpu_last - cpu_start);
    for (size_t i = 0; i < used; ++i) {
        fprintf(stderr, "%s\"%s\":{\"wall_ms\":%.9f,\"cpu_ms\":%.9f,\"entries\":%u}",
            i == 0 ? "" : ",", phases[i].name, phases[i].wall_ms,
            phases[i].cpu_ms, phases[i].count);
    }
    fputs("}}\n", stderr);
}

